structure.mermaidSource:
flowchart TD
  start_reg["Início: Identificar o verbo na oração"] --> dec_verbo{"Qual verbo sob verificação?"}
  dec_verbo -- "Aspirar" --> dec_sent_asp{"Qual o sentido de 'aspirar'?"}
  dec_sent_asp -- "Desejar / Almejar" --> proc_vti["Verbo Transitivo Indireto (VTI): EXIGE preposição 'A'"]
  dec_sent_asp -- "Respirar / Sorver" --> res_asp_vtd["VTD sem preposição: 'Aspirou o perfume'"]
  dec_verbo -- "Assistir" --> dec_sent_assist{"Qual o sentido de 'assistir'?"}
  dec_sent_assist -- "Ver / Presenciar" --> proc_vti
  dec_sent_assist -- "Ajudar / Socorrer" --> res_assist_vtd["VTD: sem preposição obrigatória ('Assistiu o paciente')"]
  dec_verbo -- "Visar" --> dec_sent_visar{"Qual o sentido de 'visar'?"}
  dec_sent_visar -- "Ter como meta / Almejar" --> proc_vti
  dec_sent_visar -- "Mirar / Pôr visto" --> res_visar_vtd["VTD sem preposição: 'Visou o alvo / o cheque'"]
  proc_vti --> dec_subst_pron{"Haverá substituição pronominal do complemento?"}
  dec_subst_pron -- "Sim (pronome)" --> res_pron_ele["USE 'A ELE(S) / A ELA(S)' e REJEITE o pronome 'LHE'"]
  dec_subst_pron -- "Não (substantivo)" --> res_termo_a["Exija a preposição 'A' antes do termo ('Aspira ao cargo', 'Assistiu ao jogo')"]
